fn element_wise_multiplication(arr1: &Vec<i32>, arr2: &Vec<i32>) -> Vec<i32> {
    // Problem statement guarantees same length and no overflow.
    arr1.iter()
        .zip(arr2.iter())
        .map(|(&a, &b)| a * b)
        .collect()
}

